package config // import "miniflux.app/v2/internal/config"

import (
	"os"
	"path/filepath"
	"testing"
)

func TestDailyConfigFileQuotedValues(t *testing.T) {
	content := `# copied from a shell env file
DATABASE_URL="postgres://user:secret@db/miniflux?sslmode=disable"
ADMIN_USERNAME='admin'
LOG_LEVEL="debug"
HTTP_CLIENT_USER_AGENT=PlainAgent/1.0
`
	filename := filepath.Join(t.TempDir(), "miniflux.conf")
	if err := os.WriteFile(filename, []byte(content), 0o600); err != nil {
		t.Fatal(err)
	}

	opts, err := NewConfigParser().ParseFile(filename)
	if err != nil {
		t.Fatalf("unexpected error parsing config file with quoted values: %v", err)
	}

	if got, want := opts.DatabaseURL(), "postgres://user:secret@db/miniflux?sslmode=disable"; got != want {
		t.Errorf("DATABASE_URL = %q, want %q", got, want)
	}
	if got, want := opts.AdminUsername(), "admin"; got != want {
		t.Errorf("ADMIN_USERNAME = %q, want %q", got, want)
	}
	if got, want := opts.LogLevel(), "debug"; got != want {
		t.Errorf("LOG_LEVEL = %q, want %q", got, want)
	}
	if got, want := opts.HTTPClientUserAgent(), "PlainAgent/1.0"; got != want {
		t.Errorf("HTTP_CLIENT_USER_AGENT = %q, want %q", got, want)
	}
}

