package request // import "miniflux.app/v2/internal/http/request"

import (
	"net/http"
	"net/url"
	"testing"
)

func TestDailyQueryBoolParamAcceptsYesNoOnOff(t *testing.T) {
	cases := []struct {
		raw          string
		defaultValue bool
		want         bool
	}{
		{"yes", false, true},
		{"Yes", false, true},
		{"on", false, true},
		{"ON", false, true},
		{"no", true, false},
		{"NO", true, false},
		{"off", true, false},
		{"Off", true, false},
		{"true", false, true},
		{"1", false, true},
		{"false", true, false},
		{"0", true, false},
	}

	for _, c := range cases {
		u, _ := url.Parse("http://example.org/?flag=" + url.QueryEscape(c.raw))
		r := &http.Request{URL: u}
		if got := QueryBoolParam(r, "flag", c.defaultValue); got != c.want {
			t.Errorf("QueryBoolParam(flag=%q, default=%v) = %v, want %v", c.raw, c.defaultValue, got, c.want)
		}
	}
}

func TestDailyQueryBoolParamUnknownValueUsesDefault(t *testing.T) {
	u, _ := url.Parse("http://example.org/?flag=maybe")
	r := &http.Request{URL: u}
	if got := QueryBoolParam(r, "flag", true); got != true {
		t.Errorf("QueryBoolParam(flag=maybe, default=true) = %v, want true", got)
	}
	if got := QueryBoolParam(r, "flag", false); got != false {
		t.Errorf("QueryBoolParam(flag=maybe, default=false) = %v, want false", got)
	}
}

