package model // import "miniflux.app/v2/internal/model"

import "testing"

func TestDailyEnclosureWebPAndAVIFAreImages(t *testing.T) {
	for _, u := range []string{
		"https://example.org/cover.webp",
		"https://example.org/cover.avif",
		"https://example.org/COVER.WEBP",
	} {
		e := &Enclosure{URL: u}
		if !e.IsImage() {
			t.Errorf("Enclosure{URL: %q}.IsImage() = false, want true", u)
		}
	}
}

func TestDailyEnclosureOtherFilesStillNotImages(t *testing.T) {
	for _, u := range []string{
		"https://example.org/episode.mp3",
		"https://example.org/notes.pdf",
	} {
		e := &Enclosure{URL: u}
		if e.IsImage() {
			t.Errorf("Enclosure{URL: %q}.IsImage() = true, want false", u)
		}
	}
}

