package filter // import "miniflux.app/v2/internal/reader/filter"

import (
	"testing"
	"time"

	"miniflux.app/v2/internal/model"
)

func TestDailyMaxAgeRuleSupportsWeeks(t *testing.T) {
	feed := &model.Feed{ID: 1, FeedURL: "https://example.org/feed.xml"}
	blockRules := ParseRules("EntryDate=max-age:2w", "")

	old := &model.Entry{Title: "old", URL: "https://example.org/old", Date: time.Now().Add(-15 * 24 * time.Hour)}
	if !IsBlockedEntry(blockRules, nil, feed, old) {
		t.Error("entry 15 days old should be blocked by max-age:2w")
	}

	recent := &model.Entry{Title: "recent", URL: "https://example.org/recent", Date: time.Now().Add(-10 * 24 * time.Hour)}
	if IsBlockedEntry(blockRules, nil, feed, recent) {
		t.Error("entry 10 days old should not be blocked by max-age:2w")
	}
}

func TestDailyMaxAgeRuleDaysStillWork(t *testing.T) {
	feed := &model.Feed{ID: 1, FeedURL: "https://example.org/feed.xml"}
	blockRules := ParseRules("EntryDate=max-age:7d", "")

	old := &model.Entry{Title: "old", URL: "https://example.org/old", Date: time.Now().Add(-8 * 24 * time.Hour)}
	if !IsBlockedEntry(blockRules, nil, feed, old) {
		t.Error("entry 8 days old should be blocked by max-age:7d")
	}
}
